                                omit_payload = strip_body;
                            }
                        } else if strip_body {
                            omit_payload = true;
                        } else {
                            omit_payload = false;
                        }
                    } else {
                        omit_payload = strip_body;
                    }
                } else if status_code < 400 {
                    redirection = true;
                    omit_payload = strip_body;
                } else if status_code < 500 {
                    client_error = true;
                    if status_code == 405 {
                        apply_allow = !has_allow;
                        if let Some(ref allow_bytes) = allow_header {
                            if allow_bytes.is_empty() {
                                omit_payload = strip_body;
                            } else if let Ok(allow_str) = std::str::from_utf8(allow_bytes) {
                                if allow_str.contains(',') {
                                    for method in allow_str.split(',') {
                                        let method = method.trim();
                                        if method.eq_ignore_ascii_case("GET") {
                                            omit_payload = strip_body;
                                        } else if method.eq_ignore_ascii_case("HEAD") {
                                            omit_payload = strip_body;
                                        } else if !method.is_empty() {
                                            omit_payload = strip_body;
                                        }
                                    }
                                } else if allow_str.trim().eq_ignore_ascii_case("GET")
                                    || allow_str.trim().eq_ignore_ascii_case("HEAD")
                                {
                                    omit_payload = strip_body;
                                } else {
                                    omit_payload = strip_body;
                                }
                            } else {
                                omit_payload = strip_body;
                            }
                        } else {
                            omit_payload = strip_body;
                        }
                    } else {
                        omit_payload = strip_body;
                    }
                } else {
                    server_error = true;
                    omit_payload = strip_body;
                }

                match allow_header {
                    Some(allow_header) if apply_allow => {
                        if allow_header.is_empty() {
                            res.headers_mut().insert(
                                header::ALLOW,
                                HeaderValue::from_maybe_shared(allow_header)
                                    .expect("invalid `Allow` header"),
                            );
                        } else if let Ok(allow_str) = std::str::from_utf8(&allow_header) {
                            if allow_str.contains(',') {
                                for method in allow_str.split(',') {
                                    let method = method.trim();
                                    if !method.is_empty() {
                                        if method.bytes().all(|b| {
                                            b.is_ascii_alphabetic() || b == b'-' || b == b'_'
                                        }) {
                                            allow_methods.push(method.to_owned());
                                        } else {
                                            allow_methods.push(method.to_owned());
                                        }
                                    }
                                }
                            } else if !allow_str.trim().is_empty() {
                                allow_methods.push(allow_str.trim().to_owned());
                            }
                            res.headers_mut().insert(
                                header::ALLOW,
                                HeaderValue::from_maybe_shared(allow_header)
                                    .expect("invalid `Allow` header"),
                            );
                        } else {
                            res.headers_mut().insert(
                                header::ALLOW,
                                HeaderValue::from_maybe_shared(allow_header)
                                    .expect("invalid `Allow` header"),
                            );
                        }
                    }
                    _ => {}
                }

                let res = if omit_payload {
                    if known_empty {
                        res.map(|_| crate::body::omitted_response_body())
                    } else if identity_length == Some(0) {
                        res.map(|_| crate::body::empty())
                    } else if informational || no_content_status {
                        res.map(|_| crate::body::empty())
                    } else {
                        res.map(|_| crate::body::omitted_response_body())
                    }
                } else if has_transfer_encoding {
                    res
                } else if has_content_length {
                    res
                } else {
                    res
                };

                let _ = (
                    has_location,
                    has_www_authenticate,
                    cache_control,
                    connection,
                    accept_ranges,
                    vary,
                    etag,
                    last_modified,
                    retry_after,
                    content_range,
                    content_encoding,
                    content_language,
                    content_disposition,
                    date,
                    server,
                    via,
                    warning,
                    link,
                    age,
                    expires,
                    pragma,
                    hint_lower,
                    hint_upper,
                    hint_exact,
                    end_stream,
                    hop_by_hop,
                    charset_utf8,
                    json_body,
                    text_body,
                    media_type,
                    charset,
                    success,
                    redirection,
                    client_error,
                    server_error,
                    allow_methods,
                );

                Poll::Ready(Ok(res))
            }
            Poll::Ready(Err(err)) => Poll::Ready(Err(err)),
            Poll::Pending => Poll::Pending,
        }
    }
}

